Emitter(Cone)

Requires(
	vec3 position;
	vec3 velocity;
)

Params(
	@position
	vec3 position;

	@direction(at = position, length = 64)
	vec3 axis;

	@range(min = 0, max = 3.1415927, step = 0.0174533)
	@cone(at = position, axis = axis, inner = min_speed, outer = max_speed)
	float spread;

	@range(min = 0, step = 0.1)
	float min_speed;
	float max_speed;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position = params.position;

	vec3 axis = dot(params.axis, params.axis) > 0.0
		? normalize(params.axis)
		: vec3(0.0, 1.0, 0.0);

	// Uniform over the spherical cap within `spread` of the axis: uniform in
	// the cosine of the angle off the axis, uniform in the turn around it
	float cos_angle = mix(cos(params.spread), 1.0, rand());
	float sin_angle = sqrt(max(0.0, 1.0 - cos_angle * cos_angle));
	vec2 rim = unit_vec(rand() * TAU) * sin_angle;

	// Orthonormal basis around the axis
	vec3 helper = abs(axis.y) < 0.99 ? vec3(0.0, 1.0, 0.0) : vec3(1.0, 0.0, 0.0);
	vec3 tangent = normalize(cross(helper, axis));
	vec3 bitangent = cross(axis, tangent);
	vec3 dir = tangent * rim.x + bitangent * rim.y + axis * cos_angle;

	particle.velocity = dir * rand_range(params.min_speed, params.max_speed);
}

Emitter(Lifetime)

Requires(
	float lifetime;
)

Params(
	@range(min=0, step=0.1)
	float min_lifetime;
	float max_lifetime;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.lifetime = rand_range(params.min_lifetime, params.max_lifetime);
}

Affector(Age)

Requires(
	float lifetime;
)

Params(
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.lifetime -= ctx.dt;
}

Affector(Gravity3D)

Requires(
	vec3 velocity;
)

Params(
	@range(step = 1)
	@vector(scale = 0.25)
	vec3 gravity;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.velocity += params.gravity * ctx.dt;
}

Affector(Bounce)

// Bounces particles off a horizontal floor (y up)

Requires(
	vec3 position;
	vec3 velocity;
)

Params(
	@range(step = 1)
	float floor;

	@range(min = 0, max = 1, step = 0.01)
	float bounciness;
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	if (particle.position.y < params.floor) {
		particle.position.y = params.floor;
		particle.velocity = deflect(particle.velocity, vec3(0.0, 1.0, 0.0), params.bounciness);
	}
}

Affector(Integrate3D)

Requires(
	vec3 position;
	vec3 velocity;
)

Params(
)

void process(inout ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	particle.position += particle.velocity * ctx.dt;
}

Renderer(Billboard)

Requires(
	vec3 position;
	float lifetime;
)

Params(
	@range(min = 0, step = 0.1)
	vec2 size;
	@color
	uint color;
)

#if GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_VERTEX

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	if (particle.lifetime > 0.0) {
		// Camera-facing: the corner offset is applied in view space
		gl_Position = billboard(particle.position, quad() * params.size);
	} else {
		cull();
	}
}

#elif GRAIN_SHADER_STAGE == GRAIN_SHADER_STAGE_FRAGMENT

void process(ParticleAttrs particle, ModuleParams params, Ctx ctx) {
	// The color param is straight alpha while blending is premultiplied
	grain_Color = premultiply(unpackUnorm4x8(params.color))
		* clamp(particle.lifetime, 0.0, 1.0);
}

#endif
